import json
from pathlib import Path
import numpy as np

root=Path(__file__).resolve().parents[1]; out=root/'auto-parking-experimental'; v4=json.loads((out/'experimental_v4_diagnostics.json').read_text()); v5=json.loads((out/'experimental_v5_diagnostics.json').read_text())
def dist(vals):
 vals=[x for x in vals if x is not None];
 if not vals:return {'defined':0,'undefined':'not_available'}
 q=np.quantile(vals,[.25,.5,.75]); return {'defined':len(vals),'min':float(min(vals)),'q1':float(q[0]),'median':float(q[1]),'q3':float(q[2]),'max':float(max(vals))}
pairs=v5.get('merge_candidates',[]); weak=[f for f in v5['fragments'] if f['anchor_count']<3]; strong=[f for f in v5['fragments'] if f['anchor_count']>=3]
measurements={k:dist([p.get(k) for p in pairs]) for k in ['normalized_lateral_separation','normalized_endpoint_distance','local_scale_ratio']}
analysis={'frozen_counts':{'anchors':67,'components':31,'accepted_rows':7,'assigned_anchors':37,'unassigned_anchors':30,'fragments':31,'pairs':465,'logical_rows':7,'accepted_merges':0,'recovered_fragments':0,'unknown_anchors':30},'measurement_completeness':{'fragment_pairs':len(pairs),'all_requested_fields_defined':False,'undefined_policy':'null plus explicit status; current V4 lacks complete segment/axis endpoint evidence for some components'},'distributions':measurements,'accepted_row_pair_analysis':{'count':21,'records':'See fragment_pair_measurements; no merges performed'},'weak_component_row_analysis':{'weak_components':len(weak),'accepted_row_fragments':len(strong)*7,'records':'component-level measurements require complete endpoint geometry'},'ambiguity_analysis':[{'component_id':f['source_component_ids'][0],'classification':'INSUFFICIENT_GEOMETRY'} for f in weak], 'proposed_gates':[{'gate':'A','name':'geometry availability'},{'gate':'B','name':'axial orientation compatibility'},{'gate':'C','name':'normalized lateral compatibility'},{'gate':'D','name':'endpoint/longitudinal continuity'},{'gate':'E','name':'local-scale compatibility'},{'gate':'F','name':'merged coherence revalidation'},{'gate':'G','name':'ambiguity check'},{'gate':'H','name':'post-merge anti-transitive validation'}], 'threshold_proposals':[{'measurement':k,'proposal':'NOT_ENOUGH_EVIDENCE','reason':'No threshold selected before complete distributions and synthetic calibration'} for k in ['orientation_difference','normalized_lateral_separation','normalized_endpoint_distance','local_scale_ratio','merged_perpendicular_dispersion','merged_orientation_dispersion']], 'strong_fragment_merge_policy':['all gates must pass','recompute merged geometry after every merge','preserve supported_segments','reject if any member becomes incoherent'], 'weak_fragment_recovery_policy':['require one clearly preferred row','leave ambiguous destinations UNKNOWN','never use image count as sole hard gate'], 'synthetic_policy_test_plan':['collinear gap','parallel rows','large lateral offset','large longitudinal gap','weak endpoint','between-row ambiguity','A-B-C bridge','high merged dispersion','perspective scale','one-anchor unknown orientation','two-anchor uncertain orientation','unsupported gap preservation','multiple destinations UNKNOWN','deterministic ordering']}
(out/'experimental_v5_policy_analysis.json').write_text(json.dumps(analysis,indent=2)); print(json.dumps({'pairs':len(pairs),'weak_components':len(weak),'logical_rows':7,'accepted_merges':0},indent=2))
